// Header dropdowns: keep only one open, close on outside click or Escape.
(() => {
  const drops = [...document.querySelectorAll(".nav-drop")];
  if (!drops.length) return;
  const closeAll = (except) => drops.forEach((d) => d !== except && d.removeAttribute("open"));
  drops.forEach((d) => d.addEventListener("toggle", () => d.open && closeAll(d)));
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".nav-drop")) closeAll();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    const open = drops.find((d) => d.open);
    if (open) {
      open.removeAttribute("open");
      open.querySelector("summary").focus();
    }
  });
})();

// Copy buttons: [data-copy-link] copies a URL, [data-copy-target] copies another element's text.
document.addEventListener("click", async (event) => {
  const button = event.target.closest("[data-copy-link], [data-copy-target]");
  if (!button) return;
  const text = button.dataset.copyLink ?? document.getElementById(button.dataset.copyTarget)?.innerText;
  if (!text) return;
  const label = button.textContent;
  try {
    await navigator.clipboard.writeText(text.trim());
    button.textContent = "Copied";
  } catch {
    button.textContent = "Press and hold to copy";
  }
  setTimeout(() => (button.textContent = label), 1800);
});

// FAQ topic tabs. Without this script every question group stays visible.
document.querySelectorAll("[data-faq]").forEach((faq) => {
  const tabList = faq.querySelector(".faq-tabs");
  if (!tabList) return;
  const tabs = [...tabList.querySelectorAll("[data-faq-tab]")];
  const panels = [...faq.querySelectorAll("[data-faq-group]")];

  const select = (name) => {
    tabs.forEach((t) => t.setAttribute("aria-selected", String(t.dataset.faqTab === name)));
    panels.forEach((p) => (p.hidden = p.dataset.faqGroup !== name));
  };

  tabList.hidden = false;
  tabList.addEventListener("click", (event) => {
    const tab = event.target.closest("[data-faq-tab]");
    if (tab) select(tab.dataset.faqTab);
  });
  select(tabs[0].dataset.faqTab);
});

// "What you pay today" calculator: adds up the ticked apps and the saving.
document.querySelectorAll("[data-calculator]").forEach((calc) => {
  const hubnex = Number(calc.dataset.hubnex);
  const total = calc.querySelector("[data-total]");
  const save = calc.querySelector("[data-save]");
  const money = (n) => `$${Number.isInteger(n) ? n : n.toFixed(2)}`;

  const update = () => {
    const sum = [...calc.querySelectorAll("input[data-price]:checked")].reduce(
      (s, input) => s + Number(input.dataset.price),
      0,
    );
    const rounded = Math.round(sum * 100) / 100;
    total.textContent = money(rounded);
    save.textContent = money(Math.max(0, Math.round((rounded - hubnex) * 100) / 100));
  };

  calc.addEventListener("change", update);
  update();
});
